function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // old telephone
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.rect(W/2 - 10, H/2 + 20, 20, 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.rect(W/2 - 5, H/2 + 70, 10, 20);
  ctx.stroke();

  // rotary dial
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + 50 + 30 * Math.cos(i * Math.PI / 5 + Math.sin(t)), 
            H/2 + 30 * Math.sin(i * Math.PI / 5 + Math.sin(t)), 5, 0, 2 * Math.PI);
    ctx.fill();
  }

  ctx.restore();
}
